/**
 * @method
 * @name btn_linedelete_onclick
 * @description 「파일삭제」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_linedelete_onclick = function() {
    try {
        dts_fileList.setBroadcast(false);
        for (let j = 1; j < dts_fileList.getRowCount() + 1; j++) {
            if (dts_fileList.getCellData(j, "SEQ") === 1) {
                dts_fileList.removeRow(j);
                // dts_fileList.NameString(2, "SEQ") = 2;
                txb_file_name.setValue("");
                scwin.file_flag = "Y";
                break;
            }
        }
        dts_fileList.setBroadcast(true, true);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07104.btn_linedelete_onclick" });
    }
};

