/**
 * @method
 * @name setParDtl
 * @description set Par Dtl 처리
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.setParDtl = function(arrPar) {
    dts_Cmt.setCellData(dts_Cmt.getRowPosition(), "FORN_COM_FST_LIST_CNTR_CD", arrPar[0]);
    dts_Cmt.setCellData(dts_Cmt.getRowPosition(), "FORN_COM_SCND_LIST_CNTR_CD", arrPar[1]);
    dts_Cmt.setCellData(dts_Cmt.getRowPosition(), "FORN_FST_LIST_MISC_CNTR_NM", arrPar[2]);
    dts_Cmt.setCellData(dts_Cmt.getRowPosition(), "FORN_SCND_LIST_MISC_CNTR_NM", arrPar[3]);
    scwin.setFornListCntrNm();
};

/**
 * @method
 * @name setFornListCntrNm
 * @description set Forn List Cntr Nm 처리
 * @returns {void}
 * @hidden N
 */
scwin.setFornListCntrNm = function() {
    const FORN_COM_FST_LIST_CNTR_CD = dts_Cmt.getCellData(dts_Cmt.getRowPosition(), "FORN_COM_FST_LIST_CNTR_CD");
    const FORN_COM_SCND_LIST_CNTR_CD = dts_Cmt.getCellData(dts_Cmt.getRowPosition(), "FORN_COM_SCND_LIST_CNTR_CD");
    let FORN_FST_LIST_MISC_CNTR_NM = dts_Cmt.getCellData(dts_Cmt.getRowPosition(), "FORN_FST_LIST_MISC_CNTR_NM");
    let FORN_SCND_LIST_MISC_CNTR_NM = dts_Cmt.getCellData(dts_Cmt.getRowPosition(), "FORN_SCND_LIST_MISC_CNTR_NM");
    switch (FORN_COM_FST_LIST_CNTR_CD) {
        case '1':
            FORN_FST_LIST_MISC_CNTR_NM = '중국';
            break;
        case '2':
            FORN_FST_LIST_MISC_CNTR_NM = '일본';
            break;
        case '3':
            FORN_FST_LIST_MISC_CNTR_NM = '미국';
            break;
        default:
            break;
    }
    switch (FORN_COM_SCND_LIST_CNTR_CD) {
        case '1':
            FORN_SCND_LIST_MISC_CNTR_NM = '중국';
            break;
        case '2':
            FORN_SCND_LIST_MISC_CNTR_NM = '일본';
            break;
        case '3':
            FORN_SCND_LIST_MISC_CNTR_NM = '미국';
            break;
        default:
            break;
    }
    tbx_foreign1.setValue(FORN_FST_LIST_MISC_CNTR_NM);
    tbx_foreign2.setValue(FORN_SCND_LIST_MISC_CNTR_NM);
};
